import test from 'node:test';
import assert from 'node:assert/strict';
import {clamp} from '../src/clamp.js';
test('下界',()=>assert.equal(clamp(-1,0,10),0));
test('上界',()=>assert.equal(clamp(11,0,10),10));
test('范围内保持',()=>assert.equal(clamp(4,0,10),4));

