import test from 'node:test';
import assert from 'node:assert/strict';
import {mayRead} from '../src/access.js';
test('同租户管理员',()=>assert.equal(mayRead({role:'admin',tenantId:'a'},{tenantId:'a'}),true));
test('不同租户管理员',()=>assert.equal(mayRead({role:'admin',tenantId:'a'},{tenantId:'b'}),false));
test('普通用户无权',()=>assert.equal(mayRead({role:'viewer',tenantId:'a'},{tenantId:'a'}),false));

